<template>
    <div v-if="isLoading">
        <!-- shimmer -->
        <div class="card card-animate">
            <div class="card-body">
                <div class="card-head-title position-relative">
                    <SieShimmer :shape="'rectangle'" :width="'100%'" :height="'20px'" :borderRadius="'8px'" />
                </div>
                <div class="d-flex justify-content-between">
                    <div class="w-50">
                        <h2 class="my-4 ff-secondary fw-semibold">
                            <SieShimmer :shape="'rectangle'" :width="'65px'" :height="'44px'" :borderRadius="'8px'" />
                        </h2>
                        <div class="d-flex justify-content-between mt-4">
                            <div class="align-self-center">
                                <SieShimmer :shape="'rectangle'" :width="'50px'" :height="'20px'"
                                    :borderRadius="'8px'" />
                            </div>
                            <div class="ml-2">
                                <SieShimmer :shape="'rectangle'" :width="'150px'" :height="'20px'"
                                    :borderRadius="'8px'" />
                            </div>
                        </div>
                    </div>
                    <div class="align-self-center">
                        <SieShimmer :shape="'circle'" :width="'100%'" :height="'56px'" />
                    </div>
                </div>
            </div><!-- end card body -->
        </div> <!-- end card-->
        <!-- end of shimmer  -->
    </div>
    <div v-else>
        <div class="card card-animate card-change">
            <div class="card-body">
                <div class="card-head-title position-relative">
                    <h4 class="card-head text-muted mt-0">Indeks Perkembangan Harga</h4>
                    <div class="card-head-popover position-absolute utl-top-minus-2 utl-right-0">
                        <a href="javascript:void(0);" id="iph-card-popover" class="text-muted" variant="light">
                            <i class="fa fa-info-circle"></i>
                        </a>
                        <b-popover target="iph-card-popover" triggers="hover" placement="right"
                            custom-class="custom-popover">
                            <template v-slot:title>
                                Indeks Perkembangan Harga
                            </template>
                            <div>
                                Indeks perkembangan harga adalah angka yang menunjukkan perubahan harga rata-rata dari suatu kelompok barang/jasa dalam periode waktu mingguan, data yang tersedia pada widget ini adalah data <span class="badge badge-outline-primary badge-secondary">IPH Terbaru.</span>
                            </div>
                        </b-popover>
                    </div>
                </div>
                <div class="d-flex justify-content-between">
                    <div>
                        <h2 class="mt-4 ff-secondary fw-semibold"><span class="counter-value" data-target="">{{
                                formattedMtMValue()
                                }}</span>
                        </h2>
                        <div class="d-flex justify-content-between mt-4 mb-1">
                            <div class="align-self-center">
                                <span :class="getBadgeClass(priceIPHChangesData.status)"> <i
                                        :class="getIconClass(priceIPHChangesData.status)" class="align-middle"></i>
                                    {{ priceIPHChangesData.persentase_perubahan || 'N/A' }} %
                                </span>
                            </div>
                            <div class="ml-2">
                                <p class="mb-0 text-muted fs-12 position-absolute"> Dibanding minggu <span
                                        class="fs-9 badge badge-outline-primary badge-secondary">Ke -{{
                                        priceIPHChangesData.kode_minggu - 1 }}</span></p>
                            </div>
                        </div>
                    </div>
                    <div class="align-self-center">
                        <div class="avatar-md flex-shrink-0 mt-n4"><span
