</template>
<script>
import { payloadHelper } from '~/helpers/payload.helper';

export default {
    data() {
        return {
            isLoading: true,
            priceIPHChangesData: {}
        }
    },
    mounted() {
        this.checkAuth().then((status) => {
            if (status == 500) {
                this.$nuxt.error({ statusCode: 500, message: 'err message' })
            } else {
                this.$store.dispatch('notification/clear');
                this.fetchIPHDataPriceChanges();
            }
        });
    },
    methods: {
        async checkAuth() {
            return this.$userCheckAuth.checkAuth(this.moduleId);
        },
        async fetchIPHDataPriceChanges() {
            let normalParam = payloadHelper.normalParam('');
            return this.$summaryAggIPHPriceIndex.getByParam(normalParam)
                .then(response => {
                    if (response.status === 'OK') {
                        this.priceIPHChangesData = response.result;
                    }
                    console.log('priceIPHChangesData ::', this.priceIPHChangesData);
                })
                .finally(() => {
                    console.log('priceIPHChangesData completed');
                    this.isLoading = false;
                })
                .catch(error => {
                    console.error('Error fetching price changes data:', error);
                });
        },
        getBadgeClass(keterangan) {
            return keterangan === 'NAIK' ? 'badge bg-light text-danger' : 'badge bg-light text-success';
        },
        getIconClass(keterangan) {
            return keterangan === 'TURUN' ? 'ri-arrow-down-line' : 'ri-arrow-up-line';
        },
        formattedMtMValue() {
            return this.priceIPHChangesData.iph
                ? this.priceIPHChangesData.iph
                : '0,00';
        },
    },
}
</script>